import { describe, expect, it } from 'vitest';
import { SnapshotFS, SnapshotResolver, extractFileFacts, pickExportTarget, type Resolution } from '@atlas/analyzer-ts';

/**
 * Resolver acceptance fixture (task P0.2). Expected outcomes below are written by hand
 * from TypeScript's documented resolution rules and the plan's precedence (§9.3); they
 * are not generated by running the analyzer.
 */
const json = (value: unknown) => JSON.stringify(value, null, 2);

const files: Record<string, string> = {
  'package.json': json({ name: 'root', private: true, workspaces: ['packages/*', 'apps/*'], dependencies: { react: '^19.0.0' } }),
  'tsconfig.base.json': `{
    // JSONC with comments and trailing commas
    "compilerOptions": { "module": "esnext", "moduleResolution": "bundler", "paths": { "@app/*": ["./apps/web/src/*"] }, },
  }`,
  'apps/web/package.json': json({ name: '@demo/web', dependencies: { '@demo/core': 'workspace:*', lodash: '^4.17.21' } }),
  'apps/web/tsconfig.json': json({ extends: '../../tsconfig.base.json', include: ['src'] }),
  'apps/web/src/main.tsx': [
    `import { add } from '@demo/core';`,
    `import { fmt } from '@demo/core/format';`,
    `import type { Shape } from '@app/types';`,
    `import Button from './ui/Button';`,
    `import './styles.css';`,
    `import data from './data.json';`,
    `import { readFile } from 'node:fs';`,
    `import path from 'path';`,
    `import _ from 'lodash';`,
    `import { z } from 'zod';`,
    `import { x } from './missing';`,
    `import { y } from '@app/nope';`,
    `import { w } from '~/thing';`,
    `import gen from './generated/out';`,
    `import k from './CASE';`,
    `const lazy = import('./lazy');`,
    `import remote from 'https://cdn.example/x.js';`,
    `export * from './ui/Button';`,
    `import { old } from '@demo/legacy';`,
    `import test from 'node:test';`,
    `import bareTest from 'test';`,
  ].join('\n'),
  'apps/web/src/types.ts': 'export interface Shape { n: number }',
  'apps/web/src/ui/Button.tsx': 'export default function Button() { return null; }',
  'apps/web/src/styles.css': 'body {}',
  'apps/web/src/data.json': '{}',
  'apps/web/src/case.ts': 'export default 1;',
  'apps/web/src/lazy.ts': 'export {};',
  'packages/core/package.json': json({
    name: '@demo/core',
    type: 'module',
    exports: { '.': { types: './src/index.ts', default: './dist/index.js' }, './format': './src/format.ts' },
  }),
  'packages/core/tsconfig.json': json({ compilerOptions: { module: 'nodenext', moduleResolution: 'nodenext', outDir: 'dist', rootDir: 'src' }, include: ['src'] }),
  'packages/core/src/index.ts': [`import { helper } from './helper.js';`, `import { bad } from './helper';`, `export * from './format.js';`, `import { fmt } from '@demo/core/format';`].join('\n'),
  'packages/core/src/helper.ts': 'export const helper = 1;',
  'packages/core/src/format.ts': 'export const fmt = 1;',
  'packages/legacy/package.json': json({ name: '@demo/legacy', main: 'dist/index.js', types: 'dist/index.d.ts' }),
  'packages/legacy/tsconfig.json': json({ compilerOptions: { outDir: 'dist', rootDir: 'src' }, include: ['src'] }),
  'packages/legacy/src/index.ts': 'export const old = 1;',
  'packages/cjs/package.json': json({ name: '@demo/cjs' }),
  'packages/cjs/index.cjs': [`const a = require('./a.cjs');`, `function f(require) { return require('./shadowed'); }`, `const dyn = require(name);`].join('\n'),
  'packages/cjs/a.cjs': 'module.exports = 1;',
  'scripts/tool.mjs': [`import x from './util';`, `import y from './util.mjs';`].join('\n'),
  'scripts/util.mjs': 'export default 1;',
  'tools/plain.js': `import p from './peer';`,
  'tools/peer.js': 'export default 1;',
  'broken/tsconfig.json': json({ extends: './a.json' }),
  'broken/a.json': json({ extends: './b.json' }),
  'broken/b.json': json({ extends: './a.json' }),
  'external-base/tsconfig.json': json({ extends: '@tsconfig/node22/tsconfig.json', include: ['*.ts'] }),
  'external-base/x.ts': `import { y } from '@/y';`,
};

const excluded = ['apps/web/src/generated/out.ts'];

function resolveAll(): Map<string, Map<string, Resolution>> {
  const fs = new SnapshotFS(Object.entries(files).map(([path, text]) => ({ path, text })), excluded);
  const resolver = new SnapshotResolver(fs);
  const out = new Map<string, Map<string, Resolution>>();
  for (const path of fs.paths()) {
    if (!/\.(?:[cm]?[jt]sx?)$/.test(path)) continue;
    const facts = extractFileFacts(path, fs.readText(path)!);
    const byKey = new Map<string, Resolution>();
    for (const imp of facts.imports) byKey.set(`${imp.kind} ${imp.specifier ?? `<${imp.unsupportedReason}>`}`, resolver.resolve(path, imp));
    out.set(path, byKey);
  }
  return out;
}

const results = resolveAll();
const get = (file: string, key: string) => {
  const value = results.get(file)?.get(key);
  if (!value) throw new Error(`No observation ${key} in ${file}: ${[...(results.get(file)?.keys() ?? [])].join(', ')}`);
  return value;
};
const pick = (r: Resolution) => ({ status: r.status, kind: r.kind, target: r.targetPath ?? r.externalName, confidence: r.confidence, reason: r.reasonCode });

describe('resolution matrix: apps/web (bundler via inherited config)', () => {
  const main = 'apps/web/src/main.tsx';
  it.each([
    ['imports-value @demo/core', { status: 'resolved-internal', kind: 'imports-value', target: 'packages/core/src/index.ts', confidence: 'inferred', reason: 'WORKSPACE_PACKAGE_MAP' }],
    ['imports-value @demo/core/format', { status: 'resolved-internal', kind: 'imports-value', target: 'packages/core/src/format.ts', confidence: 'inferred', reason: 'WORKSPACE_PACKAGE_MAP' }],
    ['imports-type @app/types', { status: 'resolved-internal', kind: 'imports-type', target: 'apps/web/src/types.ts', confidence: 'exact', reason: null }],
    ['imports-value ./ui/Button', { status: 'resolved-internal', kind: 'imports-value', target: 'apps/web/src/ui/Button.tsx', confidence: 'exact', reason: null }],
    ['imports-value ./styles.css', { status: 'resolved-internal', kind: 'imports-resource', target: 'apps/web/src/styles.css', confidence: 'inferred', reason: null }],
    // resolveJsonModule defaults to true under moduleResolution=bundler, so this is a compiler result.
    ['imports-value ./data.json', { status: 'resolved-internal', kind: 'imports-resource', target: 'apps/web/src/data.json', confidence: 'exact', reason: null }],
    ['imports-value node:fs', { status: 'builtin', kind: 'imports-value', target: 'fs', confidence: 'exact', reason: null }],
    ['imports-value path', { status: 'builtin', kind: 'imports-value', target: 'path', confidence: 'exact', reason: null }],
    ['imports-value node:test', { status: 'builtin', kind: 'imports-value', target: 'test', confidence: 'exact', reason: null }],
    // `test` is a prefix-only builtin: the bare name is an npm package.
    ['imports-value test', { status: 'resolved-external', kind: 'imports-value', target: 'test', confidence: 'inferred', reason: 'UNDECLARED_EXTERNAL_IMPORT' }],
    ['imports-value lodash', { status: 'resolved-external', kind: 'imports-value', target: 'lodash', confidence: 'exact', reason: null }],
    ['imports-value zod', { status: 'resolved-external', kind: 'imports-value', target: 'zod', confidence: 'inferred', reason: 'UNDECLARED_EXTERNAL_IMPORT' }],
    ['imports-value ./missing', { status: 'unresolved', kind: 'imports-value', target: null, confidence: null, reason: 'LOCAL_TARGET_MISSING' }],
    ['imports-value @app/nope', { status: 'unresolved', kind: 'imports-value', target: null, confidence: null, reason: 'LOCAL_TARGET_MISSING' }],
    ['imports-value ~/thing', { status: 'unresolved', kind: 'imports-value', target: null, confidence: null, reason: 'ALIAS_UNSUPPORTED' }],
    ['imports-value ./generated/out', { status: 'excluded-target', kind: 'imports-value', target: null, confidence: null, reason: 'TARGET_EXCLUDED' }],
    ['imports-value ./CASE', { status: 'unresolved', kind: 'imports-value', target: null, confidence: null, reason: 'CASE_MISMATCH' }],
    ['imports-dynamic-literal ./lazy', { status: 'resolved-internal', kind: 'imports-dynamic-literal', target: 'apps/web/src/lazy.ts', confidence: 'exact', reason: null }],
    ['imports-value https://cdn.example/x.js', { status: 'unsupported', kind: 'imports-value', target: null, confidence: null, reason: 'URL_IMPORT_UNSUPPORTED' }],
    ['reexports-value ./ui/Button', { status: 'resolved-internal', kind: 'reexports-value', target: 'apps/web/src/ui/Button.tsx', confidence: 'exact', reason: null }],
    ['imports-value @demo/legacy', { status: 'resolved-internal', kind: 'imports-value', target: 'packages/legacy/src/index.ts', confidence: 'inferred', reason: 'WORKSPACE_SOURCE_FALLBACK' }],
  ])('%s', (key, expected) => {
    expect(pick(get(main, key))).toEqual(expected);
    expect(get(main, key).contextId).toBe('apps/web/tsconfig.json');
  });

  it('records the resolver mode used', () => {
    expect(get(main, 'imports-value ./ui/Button').resolverMode).toBe('bundler/esm');
  });
});

describe('resolution matrix: packages/core (nodenext ESM)', () => {
  const index = 'packages/core/src/index.ts';
  it('maps .js specifiers to TypeScript sources', () => {
    expect(pick(get(index, 'imports-value ./helper.js'))).toEqual({ status: 'resolved-internal', kind: 'imports-value', target: 'packages/core/src/helper.ts', confidence: 'exact', reason: null });
    expect(get(index, 'imports-value ./helper.js').resolverMode).toBe('nodenext/esm');
  });

  it('does not reinterpret an explicit Node context as bundler (extensionless ESM import fails)', () => {
    expect(pick(get(index, 'imports-value ./helper'))).toMatchObject({ status: 'unresolved', reason: 'LOCAL_TARGET_MISSING' });
  });

  it('resolves self-name imports through package exports', () => {
    expect(pick(get(index, 'imports-value @demo/core/format'))).toMatchObject({ status: 'resolved-internal', target: 'packages/core/src/format.ts' });
  });

  it('keeps re-export kinds', () => {
    expect(pick(get(index, 'reexports-value ./format.js'))).toMatchObject({ status: 'resolved-internal', kind: 'reexports-value', target: 'packages/core/src/format.ts' });
  });
});

describe('resolution matrix: no-config files', () => {
  it('uses an inferred Node context for .cjs and records require mode', () => {
    const a = get('packages/cjs/index.cjs', 'requires-literal ./a.cjs');
    expect(pick(a)).toEqual({ status: 'resolved-internal', kind: 'requires-literal', target: 'packages/cjs/a.cjs', confidence: 'inferred', reason: null });
    expect(a.resolverMode).toBe('nodenext/cjs');
    expect(results.get('packages/cjs/index.cjs')!.has('requires-literal ./shadowed')).toBe(false);
    expect(pick(get('packages/cjs/index.cjs', 'requires-literal <NONLITERAL_REQUIRE>'))).toMatchObject({ status: 'unsupported', reason: 'NONLITERAL_REQUIRE' });
  });

  it('applies Node ESM rules to .mjs (extension required)', () => {
    expect(pick(get('scripts/tool.mjs', 'imports-value ./util'))).toMatchObject({ status: 'unresolved', reason: 'LOCAL_TARGET_MISSING' });
    expect(pick(get('scripts/tool.mjs', 'imports-value ./util.mjs'))).toMatchObject({ status: 'resolved-internal', target: 'scripts/util.mjs', confidence: 'inferred' });
  });

  it('uses inferred bundler rules for plain .js in an untyped package', () => {
    const r = get('tools/plain.js', 'imports-value ./peer');
    expect(pick(r)).toMatchObject({ status: 'resolved-internal', target: 'tools/peer.js', confidence: 'inferred' });
    expect(r.contextId).toBe('inferred:bundler');
  });
});

describe('configuration safety', () => {
  const fs = new SnapshotFS(Object.entries(files).map(([path, text]) => ({ path, text })), excluded);
  const resolver = new SnapshotResolver(fs);

  it('reports extends cycles and falls back instead of failing', () => {
    expect(resolver.projects.warnings).toContainEqual({ code: 'CONFIG_EXTENDS_CYCLE', path: 'broken/tsconfig.json' });
    expect(resolver.projects.contexts.map((c) => c.id)).not.toContain('broken/tsconfig.json');
  });

  it('marks package extends as incomplete context and explains alias failures', () => {
    expect(resolver.projects.warnings).toContainEqual({ code: 'CONFIG_EXTENDS_EXTERNAL', path: 'external-base/tsconfig.json' });
    expect(pick(get('external-base/x.ts', 'imports-value @/y'))).toMatchObject({ status: 'unresolved', reason: 'CONFIG_CONTEXT_MISSING' });
  });

  it('discovers the workspace map from package.json workspaces', () => {
    expect([...resolver.workspace.byName.keys()].sort()).toEqual(['@demo/cjs', '@demo/core', '@demo/legacy', '@demo/web', 'root']);
  });

  it('never reads outside the virtual snapshot', () => {
    expect(resolver.host.fileExists('/etc/passwd')).toBe(false);
    expect(resolver.host.fileExists('C:/Windows/win.ini')).toBe(false);
    expect(resolver.host.readFile('/repo/../etc/passwd')).toBeUndefined();
    expect(resolver.host.fileExists(`/repo/${'../'.repeat(5)}package.json`)).toBe(false);
  });
});

describe('package exports target selection', () => {
  it.each([
    ['./x.js', '.', './x.js'],
    [{ '.': { import: './esm.js', require: './cjs.js' } }, '.', './esm.js'],
    [{ '.': { browser: './b.js', default: './d.js' } }, '.', './d.js'],
    [{ './feature/*': './src/feature/*.ts' }, './feature/a', './src/feature/a.ts'],
    [{ import: './root.js' }, '.', './root.js'],
    [{ '.': './a.js' }, './missing', null],
  ])('%j %s', (exportsField, subpath, expected) => {
    expect(pickExportTarget(exportsField, subpath)).toBe(expected);
  });
});
